<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --configs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;benchmarks/configs/ranking/*.yaml&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
